const TEXT_CAP_ASCII = 4096, TEXT_CAP_B64 = 65536;
export const MCP_TOOLS: { name: string; description: string; inputSchema: any; handler: (a: any) => Promise<any>; raw?: boolean }[] = [
  { name: 'process_list', description: 'List connected target agent sessions', inputSchema: { type: 'object', properties: {} }, handler: async () => [...sessions.values()] },
  { name: 'backends', description: 'Injection-backend matrix: sessions by entry + device-side Zygisk pointers. Pass session to classify which paths are really loaded (zygisk / self_load). Frida Gadget is not a product backend.', inputSchema: { type: 'object', properties: { session: S } }, handler: async (a) => { const m = backendMatrix(); return a.session ? { ...m, sessionBackends: await classifySession(a.session) } : m; } },
  { name: 'dumps_list', description: 'List captured dump artifacts (dex/so/region)', inputSchema: { type: 'object', properties: {} }, handler: async () => [...dumps.values()] },
  { name: 'compat_probe', description: 'Self-assess agent env + injection footprint: tracer/seccomp/backends/exec/anon/rwx', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'compat_probe') },
{ name: 'jni_onload', description: 'List, hook, unhook, inspect or manually invoke JNI_OnLoad. hook/call work on an already-loaded module; watch arms a one-shot LOAD-TIME interception: the agent hooks the dlopen entry point and patches the JNI_OnLoad of that module as soon as it is mapped, before the VM calls it (skipOriginal+returnValue can then replace that load-time call). call is dangerous and requires confirm:true. Events are emitted as JNI_ONLOAD with phase=manual|load.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['list', 'hook', 'unhook', 'call', 'status', 'watch', 'unwatch'] }, module: S, confirm: { type: 'boolean' }, skipOriginal: { type: 'boolean' }, returnValue: N }, required: ['action'] }, handler: (a) => { if (a.action === 'call' && a.confirm !== true) return Promise.resolve({ ok: false, error: 'jni_onload call requires confirm:true' }); return agentCmd(a.session, 'jni_onload', { action: a.action, module: a.module ?? '', skipOriginal: a.skipOriginal ? 'true' : 'false', returnValue: String(a.returnValue ?? 0) }, 30_000); } },
{ name: 'jni_hook', description: 'Install, remove or inspect the global JNIEnv->RegisterNatives hook. Each registration emits a JNI_NATIVE capture event with class, method, signature and native function pointer.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['install', 'uninstall', 'status'] } }, required: ['action'] }, handler: (a) => agentCmd(a.session, 'jni_hook', { action: a.action }, 20_000) },
{ name: 'jni_env_hook', description: 'Install, remove or inspect table-slot hooks on individual JNIEnv function-table entries (FindClass / GetMethodID / GetStaticMethodID / NewStringUTF / GetStringUTFChars / GetFieldID / GetStaticFieldID / byte-array read+writeback including the primitive-array critical pair, plus every Call*Method / NewObject family in all three JNI forms - varargs, V and A - with resolved member label and rendered argument values, and since v4.55 every Get/Set<Type>Field accessor (instance + static, 9 types) so native field reads/writes are observable, and since v4.63 the string-copy/pin entries, the direct-buffer trio, the exception flow, GetJavaVM, the reference lifecycle, type introspection, monitors and weak globals, the whole array-region family (Get/Set<Type>ArrayRegion for Boolean/Char/Short/Int/Long/Float/Double) and the array-elements family (Get/Release<Type>ArrayElements for the same seven types, events carrying isCopy and the release mode copyback/commit/abort)). Patterns install or remove whole groups in one call: "*" or "all" = every slot, "Call*" = prefix, "*Field" = suffix (the whole field family), "*Field*" = contains (the field ID lookups AND the accessors - what jni_field_digest needs to resolve names). setValue (a number, single slot only) makes a Set<Type>Field hook REWRITE the write: the wrapper stores that value instead of the caller one and the event reports value=.. requested=..; object-typed fields cannot be overridden and a wildcard pattern with setValue is refused. Each captured call emits a JNI_ENV event up to a per-slot budget (then only hit/drop counters move); the hook swaps one JNIEnv table slot, so uninstall restores the original pointer and status reports the live slot value next to original.', inputSchema: { type: 'object', properties: { session: S, setValue: S, action: { type: 'string', enum: ['install', 'uninstall', 'status'] }, function: { type: 'string', description: 'Fixed entry by name - the families are the ID lookups, Call*/NewObject in all three JNI forms, Get/Set<Type>Field, the string copy/pin entries, the direct-buffer trio, the exception flow, GetJavaVM, the reference lifecycle, type introspection, monitors, weak globals, Get/Set<Type>ArrayRegion and Get/Release<Type>ArrayElements for Boolean/Char/Short/Int/Long/Float/Double (action:status lists every slot the deployed agent knows) - or a Call* family in any of the three JNI forms: CallObjectMethod[V|A], CallBooleanMethod[V|A], CallByteMethod[V|A], CallCharMethod[V|A], CallShortMethod[V|A], CallIntMethod[V|A], CallLongMethod[V|A], CallFloatMethod[V|A], CallDoubleMethod[V|A], CallVoidMethod[V|A], CallStaticObjectMethod[V|A], CallStaticBooleanMethod[V|A], CallStaticByteMethod[V|A], CallStaticCharMethod[V|A], CallStaticShortMethod[V|A], CallStaticIntMethod[V|A], CallStaticLongMethod[V|A], CallStaticFloatMethod[V|A], CallStaticDoubleMethod[V|A], CallStaticVoidMethod[V|A], NewObject[V|A]. Wildcards install/uninstall many slots at once: "*" or "all" (every entry), a prefix such as "CallIntMethod*" / "Call*", a suffix such as "*Field" / "*ArrayRegion" / "*ArrayElements", or a contains pattern such as "*Field*"; the reply reports applied/failed. Status reports per slot installed/active/hits/dropped/slotValue/original/last (so the most recent event of a slot survives a flooded capture ring), and for action:status the function field doubles as a FILTER over the same pattern language plus the keyword "installed" (only the slots that are hooked right now) - the reply then states total/matched/emitted/truncated, so a filtered or clipped listing can never be mistaken for the whole table. The agent rejects unknown names.' } }, required: ['action'] }, handler: (a) => agentCmd(a.session, 'jni_env_hook', { action: a.action, function: a.function ?? '', setValue: a.setValue ?? '' }, 20_000) },
{ name: 'javahook_probe', description: 'Probe the optional statically linked LSPlant Java-method hook backend: compile-time availability and one-time ART initialization status. It does not install a hook by itself.', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'javahook_probe', {}, 20_000) },
{ name: 'java_hook', description: 'Install, remove or inspect Java method hooks through the LSPlant backend. action:crypto arms the JCA capture hooks (Cipher, Mac, MessageDigest, Signature) and action:bypass arms the Java trust-manager bypass; neither is installed at inject. action:hookAll installs every method of one class in a single call and returns hookIds plus matched (how many methods matched) - hooking all overloads or a whole class no longer needs a hand-written loop. Filter semantics differ per action: for action:hook, params is the exact parameter-type list and an empty list means a no-arg method; for action:hookAll, an empty/omitted method or params means ANY (the "*" spelling is also accepted). matched is the size of the match set and never shrinks to the install count, so a batch cut short by limit (clamped to the 64-slot ceiling and echoed back as limit) or by per-method failures is visible: the response then carries partial:true, plus matchedCapped/hookIdsTruncated when the 64-member collection budget or the response buffer was hit. stack:true captures a bounded caller chain at the hit (Class#method:line, innermost first, hook plumbing filtered) and reports it as stack in every JAVA_HOOK event plus lastStack in status - the Java analogue of the native backtrace; off by default because it walks the stack on every hit. params is a comma-separated Java parameter-type list (empty means no-arg); the target class is loaded through the app ClassLoader (inherited members are resolved through the superclass chain and the signature reports the declaring class; method "<init>" hooks a constructor, whose callback sees the arguments and whose result must remain the new object, so skipOriginal/returnValue are rejected for constructors). Multiple hooks are supported (bounded, and status reports maxHooks next to the active count); status lists every hook with hit count, last argument, last return value and last error. Each callback also emits a JAVA_HOOK event into the bounded live-capture stream.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['hook', 'hookAll', 'unhook', 'status', 'crypto', 'bypass'] }, hookId: N, className: S, method: S, params: S, skipOriginal: { type: 'boolean' }, returnValue: S, argIndex: N, argValue: S, stack: { type: 'boolean' }, limit: N }, required: ['action'] }, handler: (a) => agentCmd(a.session, 'java_hook', { action: a.action === 'hookAll' ? 'hook_all' : a.action, limit: a.limit ?? 0, hookId: a.hookId ?? 0, className: a.className ?? '', method: a.method ?? '', params: a.params ?? '', skipOriginal: a.skipOriginal ? 'true' : 'false', returnValue: a.returnValue ?? '', argIndex: a.argIndex ?? -1, argValue: a.argValue ?? '', stack: a.stack ? 'true' : 'false' }, 30_000) },
{ name: 'java_enum', description: 'Enumerate a live Java class through reflection: modifiers, superclass, interfaces, constructors, overloaded methods and fields. Read-only and uses the app ClassLoader.', inputSchema: { type: 'object', properties: { session: S, className: S }, required: ['className'] }, handler: (a) => agentCmd(a.session, 'java_enum', { className: a.className }, 20_000) },
{ name: 'java_call', description: 'Invoke a live Java method through reflection. params is a comma-separated parameter-type list; args is a JSON array of string/number/boolean/null values — an array element marshals into Object[], and a typed byte payload is written {"$bytes":"<utf8>"} or {"$bytesHex":"<hex>"}, the only way to place a byte[] INSIDE an Object[] (a dispatcher such as Bridge.entry(int, Object[]) aborts the VM when it receives a String there); field names a static field holding the receiver for instance methods. Returns the original result or a fail-loud exception. detach:true runs the call on the AGENT\'S OWN ATTACHED THREAD and returns a callId at once, so the command channel stays answerable: a method that blocks (or a dispatcher that waits for its own thread — the usual shape of a signing entry point) parks that thread instead of hanging the session until the timeout. Poll it with java_call_result.', inputSchema: { type: 'object', properties: { session: S, className: S, method: S, params: S, field: S, args: { type: 'array' }, detach: { type: 'boolean' } }, required: ['className', 'method'] }, handler: async (a) => { if (a.detach) { const sid = pickSid(a.session); const ops = sid ? sessions.get(sid)?.caps?.ops : undefined; if (ops && !ops.includes('java_call_result')) throw new Error('detached java_call needs an agent whose caps list java_call_result; this session runs an older build (update libadh_agent.so) — or drop detach to run it on the command thread, accepting that a blocking target method will hold the session'); } return agentCmd(a.session, 'java_call', { className: a.className, method: a.method, params: a.params ?? '', field: a.field ?? '', args: JSON.stringify(a.args ?? []), detach: a.detach ? 'true' : 'false' }, 20_000); } },
  { name: 'java_call_result', description: 'Result of a detached java_call. callId answers one job with state running | done | failed, elapsedMs and — when done — result: the same object a synchronous java_call returns (className/method/signature/returnType/result), or error with the target\'s own exception text. callId 0 (or omitted) lists every retained job, which is the answer to "what happened to my call" when the id was lost. waitMs (0..30000, default 0) polls every 250 ms until the job leaves running or the deadline passes, so a bounded wait does not have to be re-implemented by the caller. Only the last 16 jobs are kept: an unknown id is an explicit error, not an empty answer.', inputSchema: { type: 'object', properties: { session: S, callId: N, waitMs: N }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); const callId = Math.max(0, Number(a.callId ?? 0)); const waitMs = Math.max(0, Math.min(30_000, Number(a.waitMs ?? 0))); const started = Date.now(); let last: any = null; for (;;) { last = await agentCmd(sid, 'java_call_result', { callId }, 10_000); const state = callId > 0 ? last?.call?.state : ''; if (callId <= 0 || state !== 'running' || Date.now() - started >= waitMs) break; await new Promise((r) => setTimeout(r, 250)); } return { ...last, waitedMs: Date.now() - started }; } },
  { name: 'hw_watch', description: 'Hardware write watchpoint (perf_event_open PERF_TYPE_BREAKPOINT) set from INSIDE the target: the way to name the code that WRITES one address when the writer is a non-exported VM handler — hooking known functions cannot find it, and an instruction trace of a flattened function drowns it. action:set needs addr (absolute hex) and len (1|2|4|8, default 8); mode w (default) / rw / x. action:after (hookId + spec, e.g. spec:"x0:8") arms the watch the moment that native hook RETURNS, on the pointer in that register — the only moment a buffer a function just produced is both known and live, so this is how you catch the code that TRANSFORMS a transient buffer (rw catches the read). The FIRST access is reported as a HW_WATCH capture carrying ip (the faulting instruction), tid/pid and the kernel call chain (frames, capped:true when the kernel had more) and is also kept in status.hit, then the watch disarms itself — re-arm to catch the next one. action:status lists the slots, action:clear (slot) frees one, action:hit returns the call chain of one hit (slot, or the first slot that has one) in a small reply. status and hit are read-only and never block: they take a trylock, so a reply is still reachable while an arm is in flight (they answer busy and are safe to retry, which matters because they are the only way to learn what a watch did). Android normally sets kernel.perf_event_paranoid=2/3, which makes perf_event_open fail for an app; the reply then carries the errno instead of pretending to watch.', inputSchema: { type: 'object', properties: { session: S, action: S, addr: S, len: N, mode: S, slot: N, hookId: N, spec: S }, required: ['session'] }, handler: (a) => agentCmd(a.session, 'hw_watch', { action: a.action ?? 'status', addr: a.addr ?? '', len: Number(a.len ?? 8), mode: a.mode ?? 'w', slot: Number(a.slot ?? -1), hookId: Number(a.hookId ?? 0), spec: a.spec ?? '' }, 10_000) },
  { name: 'native_hook', description: 'Install, remove or inspect native hooks. backtrace:true makes every event carry the caller chain captured AT THE HIT (x30 + the x29 walk inside the thread stack), which native_backtrace then symbolizes. mode=got needs module+symbol; mode=inline accepts module+symbol or addr; mode=sites (module+symbol) rewrites the B/BL call sites that reach the function instead of the function entry, so the prologue of the target stays byte-identical while the CALLER bytes change (use it when the target verifies the prologue of the function itself). scope picks where to look: module (default, the target module), all (every file-backed module except JIT memfds, app code first; status reports scanned bytes and truncated when the budget stops it), or one module name/basename; sites bounds how many call sites are patched, and status lists each site with its form (b or bl), module, original and current instruction. for mode=got/inline unhook is soft by default (the patch stays installed but inactive, safe to reactivate) and hard:true really restores the original bytes after a quiesce window; mode=sites always restores the rewritten call-site instructions (the patch belongs to the agent, so there is no Dobby state to keep) and, in the rare case where a thunk page had to stay mapped because a thread was still inside it, reports the kept page as sitesPageKept in the status response (the hook itself is already gone at that point). mode=vtable (module+symbol) patches DATA slots holding the function address (function-pointer tables such as C++ vtables, callback tables, and the module own GOT entries) instead of any code, so neither the function nor any call site changes - use it for indirect calls. By default only slots in read-only mappings are touched, because a writable word that merely equals the target is as likely to be a constant; pass slotsWritable:true to include writable slots. Patching a GOT slot also redirects direct calls in that module and changes what the symbol address resolves to there (the code itself is unchanged). For mode=got the status also carries the MECHANISM, not just counters: slot (the relocation slot that was rewritten - address/target/original are all the same pre-patch slot VALUE, so without this they name nothing), slotsPatched (1; the install refuses anything else), slotCurrent (the live value, so a patch that something else overwrote is visible), pageProtRestored with pagePermsBefore/Now (the write puts the RELRO protection back; a page left writable is a footprint the target can see), installedAtMs/firstHitMs, and verdict = "fired" | "installed-never-fired". That verdict is the point: ok:true with hits:0 used to mean either "installed and never fired" or "there was no traffic to observe", and the caller could not tell them apart. slots bounds how many are patched, scope works like for sites, and status lists each slot with its module, mapping permissions, kind (got|data), original and current value. throttleMs (ms, clamped to 0..60000, 0 = off) keeps a hot hook such as read/write/futex from flooding the capture ring: the agent still applies argIndex/returnValue/skipOriginal to EVERY hit, but emits at most one event per hook per window and counts the hits it did not emit. The next emitted event carries throttled (how many hits it stands for) and status carries throttleMs plus the running throttled total, so emitted events = hits - throttled and a thinned log never looks like a quiet target. Each callback emits a NATIVE_HOOK event with the x0-x8/x18 registers through the bounded live-capture stream. mem (optional, action:hook) copies argument memory on each emitted hit, before the original function runs, into a NATIVE_HOOK_MEM capture paired by seq. Pass "auto" when the register is not known yet: each of x0-x8 that is a readable pointer is copied for 64 bytes, at most 4 windows, and plain integers are skipped. Pass "x0:64" or "x0+16:32,x2:8" when the register is already known, and prefix the register with @ to follow ONE pointer: "@x2+32:512" reads the u64 at (x2+32) and copies the window from THAT address, which is the only way to see a pointer-of-pointer - a VM frame\'s current instruction record, a dispatch slot\'s target, a list head\'s node. A deref record carries deref:true plus the resolved ptr, and reports null/unreadable instead of guessing. For a SECOND hop, reference the earlier window instead of a register: "@x2+24:32,@#1+8:256" copies 32 bytes from *(x2+24), reads the u64 at +8 inside that copy, and copies 256 bytes from the address it names (the record carries from:1). Caps are 6 windows, 1024 bytes each, 4096 bytes total (the total is the binding guard once the count exceeds 4), offset 0..65535, registers x0-x8. A bad spec is refused. Throttled hits are not copied. Empty mem copies nothing. Read the bytes from the NATIVE_HOOK_MEM row (system category, labeled 函数参数 / 入口内容); its preview is the copied text. memAfter (one window, e.g. "x0:256") is the POST-CALL twin: copied after the original returns, so it shows what the function WROTE (a compressor output buffer, a decrypted plaintext, a PRG keystream); its record carries phase:"after" and the SAME seq as the pre-call copy of that hit, in the same mem:[{reg,offset,requested,got,hex}] shape, so the documented (hookId, seq) join works on it and its preview is not blank. A hook with memAfter calls the original instead of tail-jumping to it - that is the only cost, and x0/s0 still carry the original return value. filter is a hit-time register guard ("x2=0x7320abc0" or "x2=4660", x0-x8): a non-matching hit is neither counted nor recorded and the original still runs, which is what keeps a shared dispatch site\'s stream down to the calls you asked about (measured: 166 matching hits vs 0 events for a value that never occurs). writeReg + writeOff + writeHex rewrite memory at that register on every emitted hit (1..32 hex bytes); the event reports write.ok, so a read-only or unmapped destination is a fact instead of a guess. errno (0 = off, else 1..4095) sets the callback thread\'s errno before the original runs, which neutralizes a path check without changing the target\'s code. Every event carries x0-x8/x18/x29/x30 and tid; fp (d0-d7, s0-s7, q0hi-q7hi) is present ONLY when at least one q0-q7 lane is non-zero, so integer-only calls stop paying ~600 bytes each while a call that does use the vector bank still reports all eight registers (a 0.0 argument stays distinguishable from an unused register). traceInsns:N (0 = off, the default) runs N QBDI instructions AT THE HIT on the target thread and puts the summary in the SAME event record under trace {insns, seen, stopReason, start, stopPc, capped, mnemonics:[{mnemonic,count}], first:["0x...: insn"]} - no companion record, because a second record has to be paired and pairing is exactly where this went wrong before. This is the only route to state a request-scoped VM frame still holds: capture the arguments and trace afterwards and the memory is already released. traceFrom accepts x0..x9, x29 or x30 and starts the run at the code address in that register; default is the hooked entry, and an inline hook starts in the Dobby trampoline instead because its entry carries our branch and QBDI never returns from following it. stopReason is completed, instruction-budget, time-budget, ran-away, left-range, did-not-run or reentrant, and three guards are always on: instruction budget, wall clock, executable range. Costs to accept: the traced function EXECUTES under the emulator, so it runs twice per hit and its side effects happen twice; register arguments are exact but stack-passed and float/vector arguments are not seeded; the VM is per thread and stays resident. Refused with skipOriginal/returnSet, which exist to stop the original from running. traceInsns 0 adds nothing to the record.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['hook', 'unhook', 'status'] }, hookId: N, mode: { type: 'string', enum: ['got', 'inline', 'sites', 'vtable'] }, module: S, symbol: S, addr: S, skipOriginal: { type: 'boolean' }, returnValue: S, argIndex: N, argValue: S, confirm: { type: 'boolean' }, hard: { type: 'boolean' }, sites: N, scope: S, slotsWritable: { type: 'boolean' }, backtrace: { type: 'boolean' }, throttleMs: N, mem: S, memAfter: S, filter: S, writeReg: N, writeOff: N, writeHex: S, errno: N, traceInsns: N, traceFrom: S }, required: ['action'] }, handler: async (a) => {
    if (a.mode === 'inline' && a.addr && a.confirm !== true) return { ok: false, error: 'native_hook inline addr requires confirm:true' };
    // v4.99: every raw-address hook mode goes through the shared guard, and the agent receives the
    // guard's normalized address - the agent parses bare digit strings as decimal/octal, so
    // forwarding the caller's text could patch a different address than the one that was checked.
    // action:unhook/status only use hookId; guarding them would let a stale addr block an unhook.
    let hookAddr = a.addr ? String(a.addr) : '';
    let hookSid = a.session;
    if (a.action === 'hook' && a.addr && (a.mode === 'inline' || a.mode === 'sites' || a.mode === 'vtable')) {
      const sid0 = pickSid(a.session);
      if (!sid0) throw new Error('no session');
      const guard = await assertCallableAddress(sid0, a.addr);
      if (!guard.ok) return { ok: false, error: guard.error };
      hookAddr = guard.addr;
      hookSid = sid0;                    // guard and install must talk to the same session
    }
    let memSpec = '';
    if (a.action === 'hook') {
      try { memSpec = parseMemWindows(a.mem).spec; }
      catch (e) { return { ok: false, error: (e as Error).message }; }
    }
    // Post-call window: ONE window, same syntax as mem. Validated here so a bad spec never spends a
    // slot; the agent repeats the check. This is the only way to read what a function WROTE.
    let memAfterSpec = '';
    if (a.action === 'hook' && a.memAfter !== undefined && String(a.memAfter).trim() !== '') {
      // Own grammar and own ceiling: the pre-call window caps at 1024 bytes x 4 windows, while an
      // output buffer (a whole compressed payload) is one window of up to 512. Reusing the mem
      // validator here would refuse the shapes this exists for.
      const spec = String(a.memAfter).trim();
      const m = /^x([0-8])(?:\+(\d{1,5}))?:(\d{1,4})$/.exec(spec);
      if (!m) return { ok: false, error: 'memAfter must look like x0:256 or x2+16:32 (exactly one window)' };
      const reg = Number(m[1]);
      const off = m[2] === undefined ? 0 : Number(m[2]);
      const len = Number(m[3]);
      if (!Number.isFinite(len) || len < 1 || len > 512) return { ok: false, error: 'memAfter length must be 1..512' };
      if (off > 65535) return { ok: false, error: 'memAfter offset must be 0..65535' };
      memAfterSpec = `x${reg}${off ? `+${off}` : ''}:${len}`;
    }
    // Hit-time pointer write: writeHex into *(x<writeReg> + writeOff). Validated here so a typo is
    // answered before a slot is spent; the agent validates again (it is also reachable directly).
    let writeHex = '';
    let writeReg = -1;
    const writeOff = Number.isFinite(Number(a.writeOff)) ? Math.max(0, Math.trunc(Number(a.writeOff))) : 0;
    if (a.action === 'hook' && a.writeHex !== undefined && String(a.writeHex).length > 0) {
      const hex = String(a.writeHex);
      if (!/^[0-9a-fA-F]+$/.test(hex) || hex.length % 2 !== 0) return { ok: false, error: 'writeHex must be even-length hex (1..256 bytes)' };
      if (hex.length > 512) return { ok: false, error: 'writeHex max 256 bytes' };
      const reg = Number(a.writeReg);
      if (!Number.isInteger(reg) || reg < 0 || reg > 8) return { ok: false, error: 'writeReg must be 0..8 when writeHex is set' };
      writeHex = hex; writeReg = reg;
    }
    // Errno neutralization: 0 = off. Validated here so a typo never spends a hook slot.
    const setErrno = Number.isInteger(Number(a.errno)) ? Number(a.errno) : 0;
    if (setErrno < 0 || setErrno > 4095) return { ok: false, error: 'errno must be 0 (off) or 1..4095' };
    // Hit-time register filter, validated here so a typo never spends a hook slot: one shared
    // dispatch site serves hundreds of calls per signing, so this keeps the bounded capture ring
    // pointed at the call that matters.
    let filterSpec = '';
    if (a.action === 'hook' && (a as any).filter !== undefined && String((a as any).filter).trim() !== '') {
      const spec = String((a as any).filter).trim();
      const m = /^x([0-8])\s*=\s*(0x[0-9a-fA-F]+|[0-9]+)$/.exec(spec);
      if (!m) return { ok: false, error: 'filter must look like x2=0x7320abc0 or x2=4660' };
      filterSpec = `x${m[1]}=0x${BigInt(m[2]).toString(16)}`;
    }
    // In-hook trace: 0/absent = off, so the default install payload is unchanged. Validated here so a
    // bad request never spends a slot; the agent repeats the check (it is reachable directly too).
    let traceArgs: Record<string, string | number> = {};
    if (a.action === 'hook') {
      try { traceArgs = nativeTracePayload((a as any).traceInsns, (a as any).traceFrom); }
      catch (e) { return { ok: false, error: (e as Error).message }; }
    }
    const r = await agentCmd(hookSid, 'native_hook', { action: a.action, hookId: a.hookId ?? 0, mode: a.mode ?? '', module: a.module ?? '', symbol: a.symbol ?? '', addr: hookAddr, skipOriginal: a.skipOriginal ? 'true' : 'false', returnValue: a.returnValue ?? '', argIndex: a.argIndex ?? -1, argValue: a.argValue ?? '', hard: a.hard ? 'true' : 'false', sites: a.sites ?? 0, scope: a.scope ?? '', slotsWritable: a.slotsWritable ? 'true' : 'false', backtrace: a.backtrace ? 'true' : 'false', throttleMs: normalizeThrottleMs(a.throttleMs), mem: memSpec, memAfter: memAfterSpec, writeReg, writeOff, writeHex, errno: setErrno, filter: filterSpec, ...traceArgs }, 20_000);
    // Echo WHERE the hooked address actually lives. A wrong-but-mapped address (one digit off in the
    // module offset) installs happily and then reports zero hits, which is indistinguishable from
    // "this code is not on the path" - that misreading cost two runs during the jdgs analysis. The
    // guard already resolved the address against the maps, so reporting `libjdg+0xb1f8` next to the
    // 0x8c1f8 the caller meant makes the mistake visible in the reply itself.
    if (a.action === 'hook' && hookAddr && (r as any)?.ok !== false) {
      const sid2 = pickSid(a.session) || '';
      if (sid2) {
        try {
          const maps = await sendCmd(sid2, 'maps');
          if (maps?.ok) {
            const cls = classifyAddress(maps.regions ?? [], hookAddr);
            return {
              ...r,
              targetModule: cls.path ? cls.path.split('/').pop() : null,
              targetOffset: cls.moduleOffset ?? null,
              ...(cls.path ? {} : { targetNote: 'the hooked address is not inside a file-backed module: offset math is meaningless here' }),
            };
          }
        } catch { /* the echo is a convenience; never fail the install over it */ }
      }
    }
    return r;
  } },
{ name: 'recipe', description: 'Run a named multi-step workflow over the primitives: one call instead of eight tools in the right order. action:"list" shows the recipes and what each needs. triage answers "what is this app doing" (capabilities, maps, dex files, capture window, detection surface, capture counts); capture_window arms capture, optionally runs ONE Java method as the trigger, waits, then digests what arrived; unpack cold-starts and dumps every dex of the package. Every step reports ok/ms/error and a failed step does not abort the rest, so a partial answer stays usable. Prefer this over hand-sequencing the low-level tools.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['list', 'run'] }, name: S, options: { type: 'object' } }, required: ['action'] }, handler: async (a) => {
    if (a.action === 'list') return { ok: true, recipes: listRecipes() };
    return runRecipe(String(a.name ?? ''), a.session, (a.options && typeof a.options === 'object') ? a.options : {});
  } },
{ name: 'module_watch', description: 'Report every library that gets loaded while this is on: MODULE_LOAD records with path, handle, base and size, returned by action:"list". Arm it BEFORE triggering a target that decrypts a payload into a fresh mapping (VMP / 抽取壳): the initial map of an already-loaded module never passes through here, a new one does - so this is how the payload is caught at its first appearance instead of noticing a new region in a later maps dump. start installs the dlopen hook (idempotent); stop leaves it installed but inert, so re-arming costs nothing. Records also show up as category "system" in live_captures.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['start', 'stop', 'status', 'list'] }, limit: N }, required: ['action'] }, handler: async (a) => {
    const sid = pickSid(a.session);
    if (!sid) throw new Error('no session');
    if (a.action === 'list') {
      const modules = moduleLoads(sid, Number(a.limit) || 50);
      return { ok: true, count: modules.length, modules };
    }
    return agentCmd(sid, 'module_watch', { action: a.action });
  } },
{ name: 'memory_write', description: 'Write bytes into the target process (1..4096 per call, even-length hex). The write side of memory_read: this is how a branch, a dispatch-table entry or a decrypted buffer gets CHANGED, which hooking alone cannot do. A non-writable mapping is refused with its perms in the error; pass force:true to patch it - the original protection is restored immediately and code pages get an I-cache flush. The reply carries before (the bytes that were replaced) and the host remembers it, so memory_restore can put them back. Unmapped addresses, ranges that leave their mapping, and malformed hex are refused; a prefix is never written.', inputSchema: { type: 'object', properties: { session: S, addr: S, hex: S, force: { type: 'boolean' } }, required: ['addr', 'hex'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return writeMem(sid, a.addr, a.hex, a.force === true); } },
{ name: 'memory_restore', description: 'Undo a memory_write: the host kept the bytes each write replaced, so restoring needs only the address. Without addr it lists what this session can still restore (newest last) instead of guessing. Returns the agent reply plus restored:true, or why nothing was restored.', inputSchema: { type: 'object', properties: { session: S, addr: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); if (!a.addr) return { ok: false, undo: listWriteUndo(sid), hint: 'pass addr to restore one of these' }; const r: any = await restoreMem(sid, a.addr); return r?.ok === true ? { ...r, restored: true } : r; } },
{ name: 'capabilities', description: 'What the RUNNING agent can do: every op it dispatches plus the limits that decide whether a plan is feasible (hook slots, memory windows, max write size, frame size), and the daemon limits that apply on the host side. Call this first when you do not know which operations a session supports. The answer comes from the agent itself, not from documentation: two processes can run different builds.', inputSchema: { type: 'object', properties: { session: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) return { ok: false, error: 'no session' }; const s = sessions.get(sid); return { ok: true, session: sid, package: s?.package, agentVer: s?.agentVer, caps: s?.caps ?? null, startupHooks: s?.startupHooks ?? null, host: { bodyMaxBytes: MAX_BODY_BYTES, autoAntiDebug: autoAntiDebugEnabled(), preArmPackages: settings.startup.packages } }; } },
{ name: 'settings', description: 'Read or patch daemon settings. action:"get" returns the live settings; action:"patch" merges ONLY the sections present in patch (capture + families, ui, artifacts, startup) and persists them. startup is the host-side pre-arm applied to every NEW session at hello: startup.antiDebug (default false) + startup.module + startup.extraTargets + startup.packages (empty = all). Its default plan is ptrace only, because neutralizing access/faccessat during initialization kills apps (measured); widenAfterMs + widenTargets install those LATER, on the settled process, without another command. Enabling this makes every path check in the app fail - that is the point, but it is per-target, not a default.', inputSchema: { type: 'object', properties: { action: { type: 'string', enum: ['get', 'patch'] }, patch: { type: 'object' } }, required: ['action'] }, handler: async (a) => {
    if (a.action === 'get') return { ok: true, settings, autoAntiDebug: autoAntiDebugEnabled() };
    if (a.action !== 'patch') return { ok: false, error: 'action must be get|patch' };
    const applied = mergeSettings(a.patch ?? {});
    saveSettings();
    return { ok: true, applied, settings, autoAntiDebug: autoAntiDebugEnabled() };
  } },
{ name: 'native_look', description: 'The front door for "show me what this native function was holding". action arm stands at module+symbol (or addr with confirm:true; mode defaults to inline) and copies pointer-like arguments (mem defaults to auto; backtrace defaults to true). traceInsns adds an in-hook QBDI trace of the hit (see native_hook) and read returns it as trace, with one line of it appended to text. action read takes the hookId arm returned and answers with ONE object: text is the line to show a person, windows are the copied bytes, regs are x0-x8 from the same hit. action stop removes that hook; hard defaults to false so the same address can be armed again. Do not ask the operator to join NATIVE_HOOK with NATIVE_HOOK_MEM or to invent a register name.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['arm', 'read', 'stop'] }, hookId: N, mode: { type: 'string', enum: ['got', 'inline', 'sites', 'vtable'] }, module: S, symbol: S, addr: S, confirm: { type: 'boolean' }, mem: S, backtrace: { type: 'boolean' }, hard: { type: 'boolean' }, traceInsns: N, traceFrom: S }, required: ['action'] }, handler: async (a) => {
    const sid = pickSid(a.session);
    if (!sid) throw new Error('no session');
    if (a.action === 'arm') {
      let addr = a.addr ? String(a.addr) : '';
      if (addr) {
        if (a.confirm !== true) return { ok: false, error: 'native_look arm by address requires confirm:true' };
        const guard = await assertCallableAddress(sid, a.addr);
        if (!guard.ok) return { ok: false, error: guard.error };
        addr = guard.addr;
      }
      return nativeLookArm(sid, { mode: a.mode ? String(a.mode) : undefined, module: a.module ? String(a.module) : '', symbol: a.symbol ? String(a.symbol) : '', addr, mem: a.mem === undefined ? undefined : String(a.mem), backtrace: a.backtrace !== false, traceInsns: (a as any).traceInsns === undefined ? undefined : Number((a as any).traceInsns), traceFrom: (a as any).traceFrom === undefined ? undefined : String((a as any).traceFrom) });
    }
    if (a.action === 'read') return nativeLookRead(sid, Number(a.hookId));
    if (a.action === 'stop') return nativeLookStop(sid, Number(a.hookId), a.hard === true);
    throw new Error('action must be arm, read, or stop');
  } },
{ name: 'syscall_digest', description: 'Turn watched syscall hits into an answer: groups the NATIVE_HOOK events of the hooks you pass by (syscall number, CALLER frame) with counts, time window and threads, picks the first caller frame outside libc (that is the code that issued the syscall, which is what fingerprint-collection hunting needs), decodes the argument registers through the pointers the syscall actually uses (openat/faccessat/newfstatat paths, memfd_create names, uname utsname fields, connect IPv4/IPv6, ioctl request, socket domain/type) into a per-group example plus a paths histogram - which files does this code probe - and compares the runtime x8 with the statically attributed number so a wrong attribution shows up as a mismatch instead of a mislabel. Argument decoding reads target memory, so it is bounded by decodeLimit (default 40 samples) and can be turned off with decode:false. Install the watch with syscall_watch (it sets backtrace:true) and pass its hookIds plus expected {hookId: nr}.. Counters are reported as hits/throttled/emitted: a throttled watch counts every hit (from the authoritative agent hook status), so a thinned log cannot read as a quiet target', inputSchema: { type: 'object', properties: { session: S, hookIds: { type: 'array', items: { type: 'number' } }, expected: { type: 'object' }, sinceMs: N, limit: N, maxGroups: N, decode: { type: 'boolean' }, decodeLimit: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return syscallDigest(sid, { hookIds: a.hookIds, expected: a.expected, sinceMs: a.sinceMs, limit: a.limit, maxGroups: a.maxGroups, decode: a.decode, decodeLimit: a.decodeLimit }); } },
{ name: 'java_trace', description: 'Class-level Java tracing in three explicit phases. action:start hooks every matching method of a class (hook_all semantics: method/params are optional filters, "*"/empty = any) and returns hookIds + matched + a capture cursor, KEEPING the hooks installed. action:digest drains the agent capture ring and turns the JAVA_HOOK events of those hook ids into a digest: per-method counts, first/last timestamp, threads, last argument and return, error counts, a chronological timeline (newest window) and a caller histogram when the hooks were started with stack:true. action:stop unhooks exactly the given ids (id 0 means every Java hook in the agent and is refused). Pass the cursor from start as sinceCaptureId on digest to see only events newer than that point. The digest drains the agent ring through the shared drainSession path, so it never eats records that another consumer still needs; a failed drain is reported in drain.ok instead of silently returning an empty trace. Trigger the target or let natural traffic run between start and digest.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['start', 'digest', 'stop'] }, className: S, method: S, params: S, limit: N, stack: { type: 'boolean' }, hookIds: { type: 'array', items: { type: 'number' } }, sinceCaptureId: N, maxTimeline: N, maxMethods: N, maxCallers: N }, required: ['action'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); if (a.action === 'start') return javaTraceStart(sid, { className: String(a.className ?? ''), method: a.method, params: a.params, limit: a.limit, stack: a.stack === true }); if (a.action === 'digest') return javaTraceDigest(sid, { hookIds: a.hookIds, sinceCaptureId: a.sinceCaptureId, maxTimeline: a.maxTimeline, maxMethods: a.maxMethods, maxCallers: a.maxCallers }); if (a.action === 'stop') return javaTraceStop(sid, { hookIds: a.hookIds }); throw new Error('action must be start | digest | stop'); } },
{ name: 'native_hook_all', description: 'Batch native hooking by exported-symbol pattern: give a module and a prefix/contains/exact filter and it resolves every matching exported FUNCTION from the module dump (not a hand-typed address list), installs inline hooks on up to limit of them (clamped to the 16 concurrent native slots) and returns hookIds with matched vs installedCount so truncation is visible. The batch is sized from the agent slot budget (native_hook status reports slots.max/used/free/byMode): with 0 free slots the call fails loud instead of failing symbol by symbol, and a short budget truncates the batch with limitReason explaining it. Address hooks are powerful, so confirm:true is required. action:unhook takes hookIds and removes exactly those. Filters are deterministic (address order), exclude can drop noisy names, and backtrace/throttleMs/skipOriginal/returnValue/argIndex/argValue are passed through to each hook (throttleMs keeps a hot symbol from flooding the ring; the response echoes the effective window).', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['hook', 'unhook'] }, module: S, prefix: S, contains: S, exact: S, exclude: { type: 'array', items: { type: 'string' } }, limit: N, backtrace: { type: 'boolean' }, throttleMs: N, skipOriginal: { type: 'boolean' }, returnValue: S, argIndex: N, argValue: S, hookIds: { type: 'array', items: { type: 'number' } }, confirm: { type: 'boolean' } }, required: ['action'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); if (a.action === 'unhook') return nativeUnhookAll(sid, a.hookIds); if (a.confirm !== true) return { ok: false, error: 'native_hook_all requires confirm:true (it installs inline hooks in the target)' }; return nativeHookAll(sid, { module: String(a.module ?? ''), prefix: a.prefix, contains: a.contains, exact: a.exact, exclude: a.exclude, limit: a.limit, backtrace: a.backtrace === true, throttleMs: a.throttleMs, skipOriginal: a.skipOriginal === true, returnValue: a.returnValue, argIndex: a.argIndex, argValue: a.argValue }); } },
{ name: 'syscall_trace', description: 'One-shot syscall tracing in three phases, with the static attribution threaded automatically: action:start runs syscall_watch (module + optional syscalls filter name/number) and returns hookIds plus the expected {hookId: nr} map built from the watch response, so a mis-attribution later shows up as a mismatch instead of being copied wrong. Trigger the target in between. action:digest drains the agent ring through the shared drain path and returns the syscall digest of those hooks (callers outside libc, counts, paths histogram, runtime-x8 vs attributed mismatches). action:stop unhooks exactly the ids it was given - there is deliberately no unhook-all. Sites whose number could not be attributed are reported in unattributed and their events carry the runtime x8 only. start forwards throttleMs (0 = off) to the watch, which caps how often each site reports an event.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['start', 'digest', 'stop'] }, module: S, syscalls: { anyOf: [ { type: 'array', items: { anyOf: [ { type: 'string' }, { type: 'number' } ] } }, { type: 'string' } ] }, limit: N, throttleMs: N, hookIds: { type: 'array', items: { type: 'number' } }, expected: { type: 'object' }, sinceMs: N, decode: { type: 'boolean' }, decodeLimit: N, maxGroups: N }, required: ['action'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); if (a.action === 'start') return syscallTraceStart(sid, { module: String(a.module ?? ''), syscalls: a.syscalls, limit: a.limit, throttleMs: a.throttleMs }); if (a.action === 'digest') return syscallTraceDigest(sid, { hookIds: a.hookIds, expected: a.expected, sinceMs: a.sinceMs, decode: a.decode, decodeLimit: a.decodeLimit, maxGroups: a.maxGroups }); if (a.action === 'stop') return syscallTraceStop(sid, { hookIds: a.hookIds }); throw new Error('action must be start | digest | stop'); } },
{ name: 'trace_digest', description: 'Run a QBDI instruction trace of one native function and hand back a DIGEST instead of thousands of raw instructions: loops (header, body size, iterations), call targets with counts (symbolized when the module dump allows it), memory access shapes, materialised constants with known crypto magics flagged, branch shape and the hottest instructions. The raw stream stays available through qbdi_trace; use this one when the question is what the function DOES rather than what the exact instruction order was.. The reply carries seen/truncated/cap: a clipped trace (agent cap or reply-buffer limit) is flagged, and the digest describes the recorded prefix only. stopReason says why the run ended and is the field to check first: "completed" is the only value that makes retval a return value and the digest a description of the whole function; "instruction-budget" means the 200000-instruction bound stopped execution (the function did not finish); "time-budget" means the wall-clock bound (timeBudgetMs, 4000 default) stopped it first - an instruction budget bounds the WORK, not the TIME, and a synchronous interpreter was measured holding the command channel for the full 60s client timeout with the instruction budget never reached, which the caller can only read as "timed out"; "ran-away" means the next instruction was not in any executable mapping, so the VM was stopped BEFORE running it - stopPc names the address it was about to execute, retvalValid is false, and the digest covers only the instructions before the jump. That guard exists because a traced function can hand control to a non-code address: measured on libjdg, the run ended at pc=0x2a and the target died with SIGBUS, which cost a target restart and a tombstone that named neither the tracer nor the hook. For the same reason a target that still carries one of our inline hooks is REFUSED: a soft unhook keeps the Dobby branch in the prologue on purpose, the tracer follows it into the trampoline, and the run never returns - the error names the hook id and its state, so hard-unhook or restart first.', inputSchema: { type: 'object', properties: { session: S, symLib: S, symbol: S, addr: S, args: { type: 'array' } }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return traceDigest(sid, { symLib: a.symLib ?? '', symbol: String(a.symbol ?? ''), addr: a.addr ?? '', args: a.args }); } },
{ name: 'native_backtrace', description: 'Caller backtrace at a native hook hit (the native analogue of Thread.backtrace). With hookId it uses the newest event of that hook: when the hook was installed with backtrace:true the agent captured the chain AT THE HIT (x30 plus the x29 walk inside the thread stack), which is the trustworthy form - reading the stack later finds memory the process has already reused. Each frame is resolved to module + offset + the nearest dynamic symbol (exact when the symbol size covers the address). Explicit fp/lr instead performs a live x29 walk, which is best effort and reports its stopReason (unreadable stack, pointer outside a writable mapping, not ascending, loop) rather than inventing frames. A library mapped straight out of an APK is reported with symbolSource=archive-mapped because no standalone ELF image exists to symbolize against.', inputSchema: { type: 'object', properties: { session: S, hookId: N, fp: S, lr: S, maxFrames: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return nativeBacktrace({ session: sid, hookId: a.hookId, fp: a.fp, lr: a.lr, maxFrames: a.maxFrames }); } },
  { name: 'native_call', description: 'Actively call a native function by module+symbol or absolute addr. A raw addr is first checked against the live maps (mapped AND executable) so a stale address - unloaded module, typo - fails on the host instead of jumping into unmapped memory inside the target; module+symbol re-resolves the maps on every call for the same reason. AAPCS64: integer/pointer args go to x0-x7 (up to 8), typed f:<float> / d:<double> args go to the FP bank (up to 8; the i-th FP argument uses d_i, and a float only fills its low 32 bits, i.e. s_i). Malformed input is rejected rather than guessed: unknown type prefix, empty argument, out-of-range number, more than 8 args per bank, or an args string over 279 bytes. The integer return is result/resultDecimal (x0); when FP args are used the d0 return is reported as fpResult/fpResultDouble/fpResultFloat with returnBank:"d0" and x0MayBeStale:true - a float return is the low 32 bits of d0, and x0 is only the answer if the target returns an int. This is an arbitrary target call and requires confirm:true; it can crash the target, so use only on authorized targets.', inputSchema: { type: 'object', properties: { session: S, module: S, symbol: S, addr: S, args: { type: 'array' }, confirm: { type: 'boolean' } } }, handler: async (a) => {
    if (a.confirm !== true) return { ok: false, error: 'native_call requires confirm:true (arbitrary target call can crash the process)' };
    const sid = pickSid(a.session);
    if (!sid) throw new Error('no session');
    // v4.94/v4.97: a raw address is checked against the live maps before anything is called - the
    // shared guard keeps this tool and the REST route from drifting apart.
    const guard = await assertCallableAddress(sid, a.addr);
    if (!guard.ok) return { ok: false, error: guard.error };
    return agentCmd(sid, 'native_call', { module: a.module ?? '', symbol: a.symbol ?? '', addr: guard.addr, args: (a.args ?? []).map((v: any) => String(v)).join(',') }, 20_000);
  } },
{ name: 'stealth', description: 'Opt-in anti-detection for this session: with action:"on" the allocations the inline-hook backend makes while it is inside a Dobby call (typically its trampoline arena) stop being anonymous executable pages and land in a memfd-backed mapping named like the ART JIT cache, so a target that scans its own /proc/self/maps for an executable mapping without a path no longer sees the hook pool. It changes what the target process looks like (authorized use only) and requires confirm:true for on/off; status reports enabled/installed/active, the live GOT slot value next to the original mmap, how many allocations were redirected, and the memfd error when the platform refuses (then the real mmap is used and nothing is hidden). Default off; pools created by earlier hooks are not moved.', inputSchema: { type: 'object', properties: { session: S, action: { type: 'string', enum: ['on', 'off', 'status'] }, confirm: { type: 'boolean' } }, required: ['action'] }, handler: (a) => { const act = String(a.action ?? ''); if (act !== 'status' && a.confirm !== true) return Promise.resolve({ ok: false, error: 'stealth on/off requires confirm:true (it changes the target process footprint; authorized use only)' }); return agentCmd(a.session, 'stealth', { action: act }, 15_000); } },
{ name: 'syscall_watch', description: 'Scan one loaded module for direct svc #0 sites (libc.so is the interesting one: its stubs are what ordinary app code reaches the kernel through), attribute each site to a syscall number by decoding the MOV that precedes the svc, inline-hook up to limit of the matching sites, and report hooks whose NATIVE_HOOK events carry x8 as the runtime syscall number. syscalls filters by name or number and accepts a CSV or an array ("uname,openat,117"); a filter that matches nothing fails loud. throttleMs (0 = off) caps how often each site reports an event - hot syscalls such as read/write/futex otherwise overflow the ring and make the digest look quiet; the response echoes the effective window. Host-side orchestration: dump + static scan + native_hook; agent remains execution-only.', inputSchema: { type: 'object', properties: { session: S, module: S, limit: N, throttleMs: N, syscalls: { anyOf: [ { type: 'array', items: { anyOf: [ { type: 'string' }, { type: 'number' } ] } }, { type: 'string' } ] } }, required: ['module'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return watchSyscalls(sid, { module: a.module, limit: a.limit, syscalls: a.syscalls, throttleMs: a.throttleMs }); } },
{ name: 'got_enum', description: 'Enumerate relocation/GOT entries for one loaded module: slot address, symbol name, current resolved value and relocation type. Optional filter matches one symbol exactly.', inputSchema: { type: 'object', properties: { session: S, module: S, filter: S }, required: ['module'] }, handler: (a) => agentCmd(a.session, 'got_enum', { module: a.module, filter: a.filter ?? '' }, 20_000) },
  { name: 'memory_maps', description: 'On-demand full /proc/self/maps of the target', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'maps') },
  { name: 'mem_backend', description: 'Force which route the agent reads target memory by, for the whole session: auto (default) lets it use /proc/self/mem when the target allows that fd and fall back to an in-process direct read otherwise; direct forces the fallback everywhere. The reply states requested vs effective backend, whether it is forced, and the errno of the last /proc/self/mem open attempt. This exists because a target that refuses that fd cannot be produced on demand, so without forcing it the fallback is only ever exercised on the single read command that has a per-call override - search, magic-scan, dump and art_dexfiles would never run on it. Set it back to auto when done: it is a diagnostic, not a mode to leave on.', inputSchema: { type: 'object', properties: { session: S, backend: { type: 'string', enum: ['auto', 'direct', 'proc'] } }, required: ['backend'] }, handler: (a) => agentCmd(a.session, 'mem_backend', { backend: a.backend }) },
  { name: 'memory_read', description: 'Read target memory at hex addr for size bytes (base64 out). The reply carries requested/short, so a truncated read is visible without recomputing it from the base64 length, and via names the route that answered. via:"direct" forces the direct in-process reader for this one read instead of /proc/self/mem - use it to cross-check a target that answers /proc/self/mem with plausible garbage, or to read when the target refuses that fd (a protector that calls prctl(PR_SET_DUMPABLE,0) makes open("/proc/self/mem") fail with EACCES even for the process itself, and the read then falls back to the direct route on its own)', inputSchema: { type: 'object', properties: { session: S, addr: S, size: N, via: { type: 'string', enum: ['auto', 'direct'] } }, required: ['addr', 'size'] }, handler: (a) => agentCmd(a.session, 'read', { addr: a.addr, size: a.size, ...(a.via === 'direct' ? { via: 'direct' } : {}) }) },
  { name: 'memory_disasm', description: 'Disassemble live target memory with host-side Capstone 5 (WASM). addr is an absolute hex address, or pass module plus offset to resolve the module base from live maps. size is bounded to 64 KiB and aligned to AArch64 instructions.', inputSchema: { type: 'object', properties: { session: S, addr: S, size: N, module: S, offset: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return liveDisasm(sid, { addr: a.addr, size: a.size, module: a.module, offset: a.offset }); } },
  { name: 'memory_search', description: 'Search target memory for hex or text pattern. minAddr/maxAddr bound the scan to [lo, hi) in hex (0 or omitted = unbounded): regions outside are skipped rather than clipped, so the internal scan budget is spent on the range you asked about instead of whatever comes first in address order - on a large app the budget is otherwise exhausted by framework mappings before the scan reaches the app heap. The reply echoes the applied window, and regionClipped says whether a region inside it was still clipped.', inputSchema: { type: 'object', properties: { session: S, hex: S, text: S, limit: N, minAddr: S, maxAddr: S } }, handler: (a) => agentCmd(a.session, 'search', { pat: a.hex ?? Buffer.from(String(a.text ?? ''), 'utf8').toString('hex'), limit: a.limit ?? 256, minAddr: a.minAddr ?? '', maxAddr: a.maxAddr ?? '' }, 90_000) },
  { name: 'memory_scan_magic', description: 'Scan target memory for dex/elf/oat/vdex/zip magics. minAddr/maxAddr bound the scan to [lo, hi) in hex (0 or omitted = unbounded) - see memory_search for why aiming matters on a large app. The reply echoes the applied window, and truncated/regionClipped say whether the hit cap, the total cap or the per-region cap stopped it early, so a short list is never mistaken for a complete one.', inputSchema: { type: 'object', properties: { session: S, minAddr: S, maxAddr: S } }, handler: (a) => agentCmd(a.session, 'scan_magic', { minAddr: a.minAddr ?? '', maxAddr: a.maxAddr ?? '' }, 90_000) },
  { name: 'art_dexfiles', description: 'Enumerate loaded DexFiles via ART ClassLoader structures (no magic scan)', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'art_dexfiles', {}, 30_000) },
  { name: 'capture_start', description: 'Install the PERSISTENT hook set in this target and stream what it catches into the live store (read it with live_captures / crypto_identify / flow_correlate). This is the target-agnostic path that replaced the one-shot crypto_capture / net_capture / file_capture / detect_watch probes: the agent hardcodes neither a module nor a trigger method, so YOU name the modules here and provoke the workload with java_call {className, method, params, args}. Modules: cryptoModule (empty = scan every file-backed module and hook each one holding an EVP/SSL pointer), fileModule (empty = no file hooks), sysModule (empty = no system hooks; a comma-separated list installs ptrace, access, faccessat, __system_property_get and __system_property_read_callback on each named module, and more than 8 names sets sysTruncated). ok is a VERDICT, not the agent\'s unconditional ok:true. It re-arms from a clean slate (drain -> stop -> start) because the agent matches a GOT slot by VALUE: an install running while our own wrapper already sits in the slot reports 0 for it, which is indistinguishable from "not imported" (measured: a repeat call said 14/27, a clean re-arm said 23/27). installed is how many symbols came out live, attempted is how many the agent reported for the module set you asked for, and notInstalled names the ones that are genuinely absent from that module. With cryptoModule empty a symbol that installed nowhere is a real failure (ok:false, fail-loud); with a named module a missing symbol is normal (partial:true) because that module may not import it. complete:false whenever the answer is not fully trustworthy. Hooks stay live until capture_stop. The reply carries epoch, the newest capture id at the moment of arming: hand it to live_captures since so a read only shows what THIS arm produced (the store is per-package and survives target restarts, so without a cursor the previous run\'s records are indistinguishable from the current one\'s). After unpack_package (or during it) arming is blocked for that package to avoid SecNeo crashes — reply then has ok:false + captureSuppressed/captureProtected + error; pass force:true only if you intentionally accept the crash risk.', inputSchema: { type: 'object', properties: { session: S, cryptoModule: S, fileModule: S, sysModule: S, force: { type: 'boolean' } } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); const r = await setCapture(sid, true, { cryptoModule: a.cryptoModule, fileModule: a.fileModule, sysModule: a.sysModule, force: a.force === true }); const epoch = captures.length ? captures[captures.length - 1].id : 0; return { ...(r as any), epoch }; } },
  { name: 'capture_stop', description: 'Remove the persistent hook set for this target. DRAINS FIRST: capture_stop resets the agent ring, so stopping without draining would silently destroy everything the target produced since the last tick - the reply therefore carries drained (records pulled out and stored), drainedOk (false = the session has no drain loop, so whatever was still in the ring is gone) and dropped (the ring had already dropped records), and complete is false when either is bad. An empty result is not "nothing happened": check drained before concluding that.', inputSchema: { type: 'object', properties: { session: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return setCapture(sid, false); } },
  { name: 'file_probe', description: 'Recon which loaded module’s GOT holds open/openat/read/write/close pointers (tells you what to pass as capture_start fileModule; the agent never guesses a module)', inputSchema: { type: 'object', properties: { session: S } }, handler: (a) => agentCmd(a.session, 'file_probe', {}, 20_000) },
  { name: 'object_inspect', description: 'Read a live Java object’s fields via reflection (static field path)', inputSchema: { type: 'object', properties: { session: S, className: S, field: S }, required: ['className', 'field'] }, handler: (a) => agentCmd(a.session, 'object_inspect', { className: a.className, field: a.field }) },
  { name: 'dex_search', description: 'Search a dex (b64|sha) for strings/classes/methods', inputSchema: { type: 'object', properties: { b64: S, sha: S, query: S, kinds: { type: 'array', items: S } }, required: ['query'] }, handler: async (a) => searchDex(parseDex(await dumpBuf(a)), a.query, a.kinds) },
  { name: 'dex_index', description: 'Build or reuse the persistent SQLite index for a dex (b64|known dump sha)', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => ensureDexIndex(await dumpBuf(a)) },
  { name: 'dex_index_search', description: 'Search an indexed dex for strings, string callers, classes, fields, methods and reflection targets', inputSchema: { type: 'object', properties: { sha: S, query: S, limit: N }, required: ['sha', 'query'] }, handler: async (a) => searchDexIndex(String(a.sha), String(a.query), a.limit) },
  { name: 'dex_reflections', description: 'List statically resolved Class.forName targets and their callers from an indexed dex', inputSchema: { type: 'object', properties: { sha: S, limit: N }, required: ['sha'] }, handler: async (a) => ({ sha: a.sha, reflections: listDexReflections(String(a.sha), a.limit) }) },
  { name: 'dex_xref', description: 'Find callers of a method in a dex (b64|sha)', inputSchema: { type: 'object', properties: { b64: S, sha: S, method: S }, required: ['method'] }, handler: async (a) => { const buf = await dumpBuf(a); const { xref } = invokeXref(buf, parseDex(buf)); const q = String(a.method).toLowerCase(); const out: Record<string, string[]> = {}; for (const [c, cs] of xref) if (c.toLowerCase().includes(q)) out[c] = cs.slice(0, 200); return out; } },
  { name: 'dex_crypto_scan', description: 'Static crypto scan of a dex (API refs + algorithm strings)', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => cryptoScan(parseDex(await dumpBuf(a))) },
  { name: 'native_xref', description: 'Find the code that REFERENCES an address inside an ELF .so (b64|sha): the answer to "which function reads this constant table / jump table / state slot". offset is a MODULE offset (virtual address); if it lands in no segment it is retried as a file offset and the reply says which interpretation matched. Three forms are reported, because a strict ADRP+ADD matcher silently misses two of them and "no reference" then reads as "unused table" (that wrong conclusion cost a detour twice on a VMP-obfuscated module): add (imm12 exact), add-lsl12 (imm12 shifted by 12, how a table a few KiB away is reached), ldr/ldr32/ldr128 (page + scaled load, 4/8/16 bytes per imm12 unit) and adrp-only (the page is loaded but consumed later, e.g. through a register shuffle). An empty refs list carries a note explaining what that does and does not mean; it never pretends the table is unused.', inputSchema: { type: 'object', properties: { b64: S, sha: S, offset: S, window: N }, required: ['offset'] }, handler: async (a) => { const bytes = await dumpBuf(a); const segs = elfSegments(bytes); const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength); const want = Number.parseInt(String(a.offset).replace(/^0x/i, ''), 16); if (!Number.isFinite(want)) throw new Error('offset must be hex, e.g. 0x14e2a4'); const inVa = segs.some((s) => want >= s.vaddr && want < s.vaddr + s.fileSize); const inFile = segs.some((s) => want >= s.fileOffset && want < s.fileOffset + s.fileSize); let target = want; let interpretedAs = 'module-offset'; if (!inVa && inFile) { const seg = segs.find((s) => want >= s.fileOffset && want < s.fileOffset + s.fileSize); target = seg.vaddr + (want - seg.fileOffset); interpretedAs = 'file-offset'; } const refs = findReferences((off) => dv.getUint32(off, true), segs, target, Number(a.window) || 0); return { ok: true, target: '0x' + target.toString(16), interpretedAs, segments: segs.map((s) => ({ fileOffset: '0x' + s.fileOffset.toString(16), vaddr: '0x' + s.vaddr.toString(16), size: '0x' + s.fileSize.toString(16), executable: s.executable })), count: refs.length, refs: refs.map((r) => ({ site: '0x' + r.site.toString(16), form: r.form, value: '0x' + r.value.toString(16) })), ...(refs.length ? {} : { note: 'no ADRP in any executable segment materializes this address. That can mean the table is indexed through a base computed at runtime (VMP/OLLVM dispatch), that it lives in a module whose code was unpacked, or that it is genuinely unreferenced - it does NOT mean the feature is unused.' }) }; } },
  { name: 'native_disasm', description: 'Disassemble an ELF .so (b64|sha) by symbol', inputSchema: { type: 'object', properties: { b64: S, sha: S, symbol: S }, required: ['symbol'] }, handler: async (a) => { const t = join(tmpdir(), `mcp_${Date.now()}.so`); writeFileSync(t, await dumpBuf(a)); try { return await disasmSo(t, { symbol: a.symbol }); } finally { try { unlinkSync(t); } catch {} } } },
  { name: 'native_analyze', description: 'Exports/imports/NEEDED/printable strings of an ELF .so (b64|sha). The reply is PAGED, because a 1.6 MB obfuscated library can hold ~19 MB of strings and one unpaged call then costs more context than the analysis is worth: strings returns maxStrings entries starting at stringsOffset, with stringsTotal / nextOffset / longStrings / scanCapped describing exactly what was left out, and each entry cut at maxStringChars (default 200). Symbols are capped at 4000 per direction (exportsTruncated/importsTruncated carry the real count). counts.strings is the number of UNIQUE runs found, not the page size. minLen raises the printable-run threshold (default 4).', inputSchema: { type: 'object', properties: { b64: S, sha: S, maxStrings: N, stringsOffset: N, minLen: N, maxStringChars: N } }, handler: async (a) => { const t = join(tmpdir(), `mcp_${Date.now()}.so`); writeFileSync(t, await dumpBuf(a)); try { return await analyzeSo(t, { maxStrings: a.maxStrings, stringsOffset: a.stringsOffset, minLen: a.minLen, maxStringChars: a.maxStringChars }); } finally { try { unlinkSync(t); } catch {} } } },
  { name: 'native_crypto_const', description: 'Locate crypto by constant signatures in a stripped .so (b64|sha). Standard constants only — for a target that implements the algorithm itself and mutates it (rewritten IV / alphabet / polynomial), those signatures are absent by construction: use crypto_variant_scan instead', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => cryptoConstScan(await dumpBuf(a)) },
  { name: 'crypto_variant_scan', description: 'Identify crypto by STRUCTURE, not by standard constants: reports each family found with a verdict of standard or variant, and for a variant the evidence (which standard part is missing, and how close the rewritten one is). Catches an app that implements MD5/base64/CRC itself and perturbs it — those match no standard signature, so native_crypto_const and the runtime API-boundary capture both go blind at once. Also states where a static scan cannot see at all (runtime-generated tables, a mutation that rewrites the anchor too)', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => scanCryptoVariants(await dumpBuf(a)) },
  { name: 'native_syscall_scan', description: 'Find direct svc #0 syscalls in a .so (b64|sha) and attribute every site to a syscall number by decoding the MOV that materialises x8 before it (arm64 number table; a number that cannot be decoded statically stays unknown instead of being guessed). The same attribution backs syscall_watch, which can then hook only the sites matching a name/number filter.', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => { const buf = await dumpBuf(a); const scan = svcScan(buf); const hits = scan.hits.map((h) => { const off = Number(BigInt(h.fileOff)); const at = attributeSite(buf, off); return { ...h, syscall: at.nr == null ? null : { nr: at.nr, name: syscallName(at.nr) }, attribution: at.how }; }); return { ...scan, hits, attributedCount: hits.filter((h) => h.syscall).length, unknownCount: hits.filter((h) => !h.syscall).length }; } },
  { name: 'memory_dump', description: 'Dump target memory [addr,addr+size) to a capture artifact (sha256 dedup). The reply states complete/requestedSize: a partially readable range is still kept as an artifact but marked complete:false, a range that cannot be read at all fails instead of producing an empty dump, and the size must be a positive integer within the dump cap', inputSchema: { type: 'object', properties: { session: S, addr: S, size: N }, required: ['addr', 'size'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); const { meta, dedup } = await dumpRegion(sid, String(a.addr).replace(/^0x/, ''), Number(a.size), 'mcp'); return { ...meta, dedup }; } },
  { name: 'http_exchanges', description: 'Reassemble live TLS plaintext into whole HTTP requests. SSL_read and SSL_write stay separate records; this joins the ones that share an SSL* (the conn field capture_start stamps). HTTP/1.1 is split on Content-Length or chunked and paired in order. HTTP/2 is framed and HPACK-decoded, then paired by stream id. gzip, deflate and br are decoded. Records with no conn are counted and not paired. Filter with session and/or package. The reply always carries caveat.', inputSchema: { type: 'object', properties: { session: S, package: S } }, handler: async (a) => {
    let list = captures.filter(c => c.category === 'net');
    if (a.session) { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); list = list.filter(c => c.sessionId === sid); }
    if (a.package) list = list.filter(c => capturePackage(c) === String(a.package));
    const records: TlsChunk[] = list.map(c => ({ id: c.id, sessionId: c.sessionId, func: c.func, hex: c.hex, inl: c.inl, tsNs: c.tsNs, ts: c.ts, conn: c.conn }));
    return assembleHttpExchanges(records);
  } },
  { name: 'flow_correlate', description: 'Join the live capture store\'s crypto stream to its TLS stream: pairs a crypto record (EVP_*/HMAC_Update) with a net record (SSL_*) that ran on the SAME THREAD inside a 200ms window - the "this plaintext was encrypted, then that request went out" question, answered from the daemon\'s own store rather than by the target. Turn capture_start on and provoke the workload (java_call) first, then call this; sinceMs / sinceCaptureId bound the window. Every reply carries caveat: this is thread+time CO-OCCURRENCE, not a content-hash proof that the payloads are the same bytes (deterministic correlation is WS-I and is not implemented), and an empty result carries reason instead of a bare empty array, with storeLoss set when the requested window reaches past evicted records.', inputSchema: { type: 'object', properties: { session: S, sinceMs: N, sinceCaptureId: N, maxPairs: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return flowCorrelate(sid, { sinceMs: a.sinceMs, sinceCaptureId: a.sinceCaptureId, maxPairs: a.maxPairs }); } },
  { name: 'object_set', description: 'Write one field of a live object - the write counterpart of object_inspect (Frida-style field patching). field names the STATIC holder that carries the object (same convention as object_inspect/object_invoke), targetField is the field on that object, and value is coerced by the field declared type (boolean/int/long/float/double/String). The reply carries before/after so the effect is visible and can be put back; a final field (Kotlin val) comes back ok:false instead of pretending it worked.', inputSchema: { type: 'object', properties: { session: S, className: S, field: S, targetField: S, value: S }, required: ['session', 'className', 'field', 'targetField', 'value'] }, handler: (a) => agentCmd(a.session, 'object_set', { className: a.className ?? '', field: a.field ?? '', targetField: a.targetField ?? '', value: String(a.value ?? '') }, 20_000) },
  { name: 'jni_field_digest', description: 'Turn JNIEnv field events into "which fields did native code read or write": joins the Get/Set<Type>Field access events (field=0x..) with the GetFieldID/GetStaticFieldID events that handed those ids out, so a group reads Class#name:sig instead of an opaque pointer - the signal that shows which fields a target probes through native code. Writes that an active setValue override REWRITTEN are called out separately (group.rewritten + lastRequested vs lastValue, plus rewrittenSamples), because "the target asked for 7 and the hook stored 42" is itself the finding. Hook the field slots with jni_env_hook first (hook GetFieldID too, or ids stay unresolved), trigger the target, then call this; the drain goes through the shared drainSession path and a lossy ring is reported rather than hidden.', inputSchema: { type: 'object', properties: { session: S, sinceMs: N, limit: N, maxGroups: N } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return jniFieldDigest(sid, { sinceMs: a.sinceMs, limit: a.limit, maxGroups: a.maxGroups }); } },
  { name: 'object_invoke', description: 'Call a no-arg method on a live object (via static field path)', inputSchema: { type: 'object', properties: { session: S, className: S, field: S, method: S }, required: ['className', 'field', 'method'] }, handler: (a) => agentCmd(a.session, 'object_invoke', { className: a.className, field: a.field, method: a.method }) },
  { name: 'dex_method_code', description: 'Extract a method’s runtime code_item bytecode from a dex (b64|sha). disasm:true adds a real Dalvik disassembly next to it — one entry per instruction (offset, raw code units, mnemonic + operands), decoded by the SDK\'s dexdump -d on the host rather than by a table this project would have to keep correct. Only the matching methods are kept (class is a normalised case-insensitive substring, method a name substring), each body capped at maxInsns (default 400) with insnsTruncated telling you, and the whole reply bounded by methodMatches/returned/truncated. When the tool is absent the reply carries disasm.available:false plus the reason and the raw code_item still comes back; a dumped dex with a stale header checksum is refused by dexdump, so run dex_repair and pass the repaired bytes.', inputSchema: { type: 'object', properties: { b64: S, sha: S, class: S, method: S, disasm: { type: 'boolean' }, maxInsns: N }, required: ['class'] }, handler: async (a) => { const buf = await dumpBuf(a); const code = extractMethodCode(buf, parseDex(buf), String(a.class), a.method ? String(a.method) : undefined); if (a.disasm !== true) return code; return { code, disasm: await disassembleDex(buf, { class: String(a.class), method: a.method ? String(a.method) : '', maxInsns: a.maxInsns }) }; } },
  { name: 'dex_repair', description: 'Repair a dumped dex header (file_size/checksum/signature) and store the repaired bytes as a dump artifact. Returns the header fields plus the artifact sha256/size/kind/path. The repaired dex is deliberately NOT returned inline: a packed target dex can be 100 MB+, and the caller already holds the input bytes - index or download it by the returned sha instead. dedup:true means a byte-identical artifact was already stored.', inputSchema: { type: 'object', properties: { b64: S, sha: S } }, handler: async (a) => { const buf = await dumpBuf(a); const info = repairDexHeader(buf); const { meta, dedup } = await persistArtifact(buf, { source: 'dex-repair', addr: '', tag: 'dex_repair', sessionId: '', package: '' }); return { ...info, sha256: meta.sha256, size: meta.size, kind: meta.kind, path: meta.path, dedup }; } },
  // ---- axis 1: one-glance crypto algorithm identification ----
  { name: 'crypto_identify', description: '一眼看清目标 App 用了哪些加密算法/密钥/IV — summarize all captured crypto (algorithm, key, iv, plaintext) into a plain-language report for non-experts', inputSchema: { type: 'object', properties: {} }, handler: async () => cryptoIdentify() },
  { name: 'detect_summary', description: 'Checklist of anti-analysis behavior seen in the live capture store: debug, root/framework, signature, emulator, integrity, plus property reads. Built from ptrace/access/faccessat/sysprop/propread lines (including return value), from open/openat of /proc/self/status|maps and su/magisk paths, and from JAVA_HOOK hits of the detect_java methods. Other Java/native hooks stay out of this checklist. armed is false when capture_start did not install a system hook (sysModule empty). Does not install anything.', inputSchema: { type: 'object', properties: { session: S, package: S } }, handler: async (a) => detectionReport({ session: a.session, package: a.package }) },
  { name: 'detect_modules', description: 'Which of THIS app\'s loaded libraries import ptrace, access, faccessat or the system-property readers. Pass the package. Returns sysModule, a comma-separated list you can hand to capture_start. Does not install hooks. System libraries are excluded. A packed relocation table with no readable symbols is reported in skippedPacked instead of being treated as "imports nothing".', inputSchema: { type: 'object', properties: { session: S, package: S }, required: ['package'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return planDetectModules(sid, String(a.package ?? '')); } },
  { name: 'detect_java', description: 'Java detection hooks, installed only when confirm:true and you name the families. Families: debug (Debug.isDebuggerConnected / waitingForDebugger), root (Runtime.exec(String)), signature (ApplicationPackageManager.getPackageInfo), file (File.exists — hot path, unhook when done). Without confirm the reply is the plan and nothing is hooked. Each installed hook captures a stack. Partial installs stay in place and are listed in hookIds so you can unhook them.', inputSchema: { type: 'object', properties: { session: S, confirm: { type: 'boolean' }, families: { type: 'array', items: { type: 'string' } } } }, handler: async (a) => { const families = Array.isArray(a.families) ? a.families : String(a.families ?? '').split(',').map((s: string) => s.trim()).filter(Boolean); const plan = detectJavaPlan(families); if (a.confirm !== true) return { ok: false, error: 'detect_java requires confirm:true', plan }; const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return armDetectJava(sid, families, true); } },
  { name: 'live_captures', description: 'List the live captures streamed by the persistent hooks — crypto / net(TLS) / file / system, filterable by category (algorithm+op+preview, newest last). Each record carries func (the raw boundary that fired: EVP_CipherUpdate, SSL_write, open, ptrace, sysprop …) next to the classified algo/op, because "which function did this come from" is the question a capture answers. includeText:true adds the payload; encoding picks how. encoding:"ascii" (default) is the readable rendering — one char per byte with every non-printable replaced by ".", capped at 4096 chars — good for eyeballing and for "is this marker in the traffic" substring checks, but LOSSY: you cannot re-frame an HTTP stream, gunzip a response or recover a binary payload from it. encoding:"b64" is the exact bytes (base64, capped at 65536 bytes) and is what a parser wants. Either way each record reports bytes (true payload length) and truncated (true only if the cap cut it), so a cut is never silent. Without includeText the record is metadata only (inl already gives the length). since is a capture-id CURSOR, not a timestamp: pass the epoch capture_start returned (or the id of the last record you already read) and only newer records come back, so a second read cannot re-show the first read\'s rows and an empty reply means "nothing new" rather than "the filter missed it". hookId narrows the store to the records of ONE native hook: every NATIVE_HOOK / NATIVE_HOOK_MEM record now carries hookId, seq and phase (lifted at ingest), and seq is numbered PER HOOK, so pairing a register event with its memory record must match on hookId AND seq - joining on seq alone silently mixes two hooks. Filter with session and/or package when more than one target has ever been injected: without them the sandbox self-check records and the target\'s records are one stream, and a record is attributed by its own package stamp first, so it stays attributable after the process exits and its session is pruned.', inputSchema: { type: 'object', properties: { limit: N, category: S, session: S, package: S, since: N, hookId: N, includeText: { type: 'boolean' }, encoding: { type: 'string', enum: ['ascii', 'b64'] } } }, handler: async (a) => { let sid = ''; if (a.session) { sid = pickSid(a.session) || ''; if (!sid) throw new Error('no session'); } const all = filterLiveCaptures(captures, { category: a.category ? String(a.category) : '', session: sid, package: a.package ? String(a.package) : '', hookId: a.hookId === undefined || a.hookId === null ? undefined : Number(a.hookId) }); const since = Number(a.since) || 0; const list = since > 0 ? all.filter((c) => ((c as any).id ?? 0) > since) : all; const withText = a.includeText === true; const enc = a.encoding === 'b64' ? 'b64' : 'ascii'; const cap = enc === 'b64' ? TEXT_CAP_B64 : TEXT_CAP_ASCII; return { total: list.length, on: captureTimers.size > 0, captures: list.slice(-(Number(a.limit) || 50)).map(c => { const bytes = c.hex ? c.hex.length / 2 : 0; const truncated = bytes > cap; const text = enc === 'b64' ? b64Of(truncated ? c.hex.slice(0, cap * 2) : c.hex) : asciiOf(c.hex).slice(0, cap); return { id: c.id, source: c.source, func: c.func, category: c.category, algo: c.algo, op: c.op, inl: c.inl, tid: c.tid, ts: c.ts, tsNs: c.tsNs, preview: c.preview, ...(c.hookId !== undefined ? { hookId: c.hookId } : {}), ...(c.seq !== undefined ? { seq: c.seq } : {}), ...(c.phase ? { phase: c.phase } : {}), ...(withText ? { encoding: enc, bytes, truncated, ...(enc === 'b64' ? { b64: text } : { ascii: text }) } : {}) }; }) }; } },
  { name: 'capture_detail', description: 'Full detail of one capture by id: algorithm, key(hex), iv(hex), plaintext(utf8+hex), ciphertext(hex)', inputSchema: { type: 'object', properties: { id: N }, required: ['id'] }, handler: async (a) => { const c = captures.find(x => x.id === Number(a.id)); if (!c) throw new Error('not found'); const text = Buffer.from(c.hex, 'hex').toString('utf8'); return { ...c, text }; } },
  // ---- axis 2: one-click unpack (no AOSP flashing needed) ----
  { name: 'dex_coverage', description: '方法恢复率报告 — per-method state (native/abstract/present/extracted) + recovery rate over a dumped dex', inputSchema: { type: 'object', properties: { b64: S, sha: S }, required: [] }, handler: async (a) => { const buf = await dumpBuf(a); return analyzeCoverage(buf, parseDex(buf)); } },
  { name: 'dump_all_dex', description: '单进程 dump 已加载 DEX（ART 枚举 + SHA-256 去重）。不会冷启动、不会扫同包其它进程、不会抑制捕获布防。产品「一键脱壳」请用 unpack_package。', inputSchema: { type: 'object', properties: { session: S } }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return dumpAllDex(sid); } },
  { name: 'unpack_package', description: '产品一键脱壳：按包冷启动（可关）、抑制本包自动布防防加固闪退、扫该包全部在线进程、去重打 zip。返回 didSkipAutoArm / captureNote。不等于 dump_all_dex。', inputSchema: { type: 'object', properties: { package: S, session: S, launch: { type: 'boolean' }, forceRestart: { type: 'boolean' } } }, handler: async (a) => runUnpackBundle({ package: a.package, session: a.session, launch: a.launch !== false, forceRestart: a.forceRestart === true }) },
  { name: 'dex_recover', description: 'Recover extracted CodeItems from a restored snapshot into a base dex + rebuild (baseSha/baseB64 + restoredSha/restoredB64)', inputSchema: { type: 'object', properties: { baseB64: S, baseSha: S, restoredB64: S, restoredSha: S } }, handler: async (a) => { const base = await dumpBuf({ b64: a.baseB64, sha: a.baseSha }); const restored = await dumpBuf({ b64: a.restoredB64, sha: a.restoredSha }); const pd = parseDex(base); const { captures: caps, report } = recoverFromSnapshots(base, restored, pd); const rb = rebuildStandardDex(base, caps); const outSha = createHash('sha256').update(rb.dex).digest('hex'); const path = join(CAPTURES, `${outSha.slice(0, 16)}.dex`); if (!existsSync(path)) writeFileSync(path, rb.dex); const meta: DumpMeta = { sha256: outSha, size: rb.dex.length, source: 'dex-recover', addr: '0', tag: 'recovered', sessionId: '', package: '', capturedAt: Date.now(), path, kind: 'dex' }; rememberDump(meta); return { ...report, injected: rb.injected, sha256: outSha }; } },
  // ---- axis 3: everything the AI needs to drive a reversing session ----
  { name: 'trigger', description: 'Actively load a class (level 1) and invoke a safe static no-arg method (level 3) to force code paths — a trigger source for unpacking', inputSchema: { type: 'object', properties: { session: S, class: S, method: S, level: N }, required: ['class'] }, handler: (a) => agentCmd(a.session, 'trigger', { className: a.class, method: a.method ?? '', level: Number(a.level ?? 1) }, 20_000) },
  { name: 'qbdi_trace', description: 'QBDI instruction-level dynamic trace of a native function (per-instruction disassembly + return value), invoked with up to 8 unsigned integer/pointer args. Name the target EITHER as symLib+symbol (an exported symbol) OR as addr (absolute hex): the interesting functions in a stripped/obfuscated library are frequently not exported at all — libjdg registers its dispatcher through RegisterNatives, so its address only comes from the static method table or a backtrace. QBDI itself is loaded in the target with dlopen("libQBDI.so"), so push that library and load it first when the target does not ship it.', inputSchema: { type: 'object', properties: { session: S, symLib: S, symbol: S, addr: S, args: { type: 'array' } }, required: ['session'] }, handler: (a) => { if (!a.addr && (!a.symLib || !a.symbol)) throw new Error('qbdi_trace needs symLib+symbol or addr'); return agentCmd(a.session, 'qbdi_trace', { symLib: a.symLib ?? '', symbol: a.symbol ?? '', addr: a.addr ?? '', args: (a.args ?? []).map((v: any) => String(v)).join(',') }, 30_000); } },
  { name: 'agent_ping', description: 'Liveness and latency check for one session: sends the cheapest command the agent has and reports the measured round trip in ms. Use it to tell "the target is gone" from "this command is just slow", before and after a crash-prone operation, or when a session looks hung. It fails fast (5s) instead of sitting on a normal command timeout.', inputSchema: { type: 'object', properties: { session: S }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return agentPing(sid); } },
  { name: 'engine_selftest', description: 'Prove the native hook engine works in THIS target: the agent replaces a GOT slot in its own module, triggers a controlled call, restores it, and reports replaced / hits / fired plus the slot page permissions before and after. ok is the VERDICT (the hook fired AND the RELRO page protection was restored); commandOk only says the agent answered. A build that left the page writable comes back ok:false with a note that it is detectable, so run this before trusting hook results.', inputSchema: { type: 'object', properties: { session: S }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return hookEngineSelftest(sid); } },
  { name: 'protocol_selftest', description: 'Command-channel integrity check: send one oversized frame whose tail marker sits past the old 8192-byte single-line cap and verify the tail survived and the whole frame arrived. Use it when replies look truncated or a session looks half-dead; kb is clamped to 1..4096. ok:false here means the channel (adb reverse / framing) is at fault, not the target.', inputSchema: { type: 'object', properties: { session: S, kb: N }, required: ['session'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return protocolSelfTest(sid, a.kb); } },
  { name: 'fs_list', description: 'List a directory on the DEVICE through the target process, so it sees the sandbox the way the app does (its private /data/data/... dir, /data/local/tmp, /proc/self/...). Returns name/type/size/mode/mtime per entry plus count and truncated. Start here to find shared_prefs, databases, keystores or dropped scripts, then pull one with fs_read.', inputSchema: { type: 'object', properties: { session: S, path: S }, required: ['session', 'path'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return listDeviceDir(sid, String(a.path ?? '')); } },
  { name: 'fs_read', description: 'Read one device file through the target process. The agent caps a read at 1MB and reports truncated honestly. Returns size, byte count, a binary flag (NUL byte present), a printable preview and the line count, plus the whole text when the file is text and is at most 256KB. Binary or oversized files come back with textOmitted saying why; pass includeBase64:true for the raw bytes.', inputSchema: { type: 'object', properties: { session: S, path: S, includeBase64: { type: 'boolean' }, includeText: { type: 'boolean' }, previewBytes: N }, required: ['session', 'path'] }, handler: async (a) => { const sid = pickSid(a.session); if (!sid) throw new Error('no session'); return readDeviceFile(sid, String(a.path ?? ''), { includeBase64: a.includeBase64 === true, includeText: a.includeText !== false, previewBytes: a.previewBytes }); } },
  { name: 'load_library', description: '把任意 .so 加载进目标进程（agent 内 dlopen）。可选 symbol 探测。不是 Frida 注入入口。', inputSchema: { type: 'object', properties: { session: S, path: S, symbol: S }, required: ['path'] }, handler: (a) => agentCmd(a.session, 'load_so', { path: a.path, symbol: a.symbol ?? '' }, 30_000) },
];

export const MCP_MAP = new Map(MCP_TOOLS.map(t => [t.name, t]));

export async function handleMcp(reqBody: string, res: ServerResponse, opts?: { package?: string }) {
  let msg: any;
  try { msg = JSON.parse(reqBody); } catch { res.writeHead(400).end('bad json'); return; }
  const pin = opts?.package;
  const reply = (result?: unknown, error?: unknown) => {
    const body = JSON.stringify({ jsonrpc: '2.0', id: msg.id, ...(error ? { error } : { result }) });
    res.writeHead(200, { 'content-type': 'application/json' }); res.end(body);
  };
  if (msg.method === 'initialize') return reply({ protocolVersion: '2024-11-05', capabilities: { tools: {} }, serverInfo: { name: 'adhd', version: '0.1.0' } });
  if (msg.method === 'notifications/initialized' || msg.method === 'notifications/cancelled') { res.writeHead(202).end(); return; }
  if (msg.method === 'ping') return reply({});
  if (msg.method === 'tools/list') return reply({ tools: MCP_TOOLS.map(t => ({ name: t.name, description: t.description, inputSchema: t.inputSchema })) });
  if (msg.method === 'tools/call') {
    const name = msg.params?.name;
    const t = MCP_MAP.get(name);
    if (!t) return reply(undefined, { code: -32602, message: `unknown tool: ${name}` });
    let args = { ...(msg.params?.arguments ?? {}) };
    if (pin && name === 'process_list') {
      const out = [...sessions.values()].filter(s => s.package === pin);
      return reply({ content: [{ type: 'text', text: JSON.stringify(out, null, 2) }] });
    }
    if (pin && args.session == null) {
      const sid = sessionForPackage(pin);
      if (sid) args.session = sid;
    }
    try {
      const out = await t.handler(args);
      if (t.raw) return reply(out);
      return reply({ content: [{ type: 'text', text: JSON.stringify(out, null, 2) }] });
    } catch (e) { return reply({ content: [{ type: 'text', text: 'error: ' + (e as Error).message }], isError: true }); }
  }
  return reply(undefined, { code: -32601, message: `method not found: ${msg.method}` });
}
